32	// Pending approval resolvers (in-process — lives in module scope)
33	const pendingApprovalResolvers = new Map();
34	
35	function waitForApproval(runId, nodeId, nodeLabel, timeoutMinutes = 60) {
36	  return new Promise((resolve, reject) => {
37	    const key = `${runId}:${nodeId}`;
38	    const timer = setTimeout(() => {
39	      pendingApprovalResolvers.delete(key);
40	      saveApprovals(loadApprovals().filter(a => a.key !== key));
41	      reject(new Error(`Approval timed out after ${timeoutMinutes} minutes`));
42	    }, timeoutMinutes * 60 * 1000);
43	
44	    pendingApprovalResolvers.set(key, { resolve, reject, timer });
45	
46	    const approvals = loadApprovals();
47	    approvals.push({ key, runId, nodeId, nodeLabel, createdAt: new Date().toISOString(), timeoutMinutes });
48	    saveApprovals(approvals);
49	  });
50	}
