84	async function sendFailureAlert(agentName, nodeLabel, error, orchestrationName) {
85	  try {
86	    const settings = loadGlobalSettings();
87	    const url = settings.slackWebhookUrl;
88	    if (!url || !settings.alertOnFailure) return;
89	    const payload = {
90	      text: `:warning: *Agent Failure* in Polyglot`,
91	      blocks: [
92	        { type: 'header', text: { type: 'plain_text', text: 'Agent Failure Alert' } },
93	        { type: 'section', fields: [
94	          { type: 'mrkdwn', text: `*Agent:*\n${agentName}` },
95	          { type: 'mrkdwn', text: `*Node:*\n${nodeLabel}` },
96	          { type: 'mrkdwn', text: `*Pipeline:*\n${orchestrationName || 'Direct'}` },
97	          { type: 'mrkdwn', text: `*Error:*\n${(error || '').slice(0, 200)}` },
98	        ]},
99	      ],
100	    };
101	    const http = require('http');
102	    const https = require('https');
103	    const parsed = new URL(url);
104	    const lib = parsed.protocol === 'https:' ? https : http;
105	    const req = lib.request({ hostname: parsed.hostname, port: parsed.port, path: parsed.pathname, method: 'POST', headers: { 'Content-Type': 'application/json' } });
106	    req.on('error', () => {});
107	    req.write(JSON.stringify(payload));
108	    req.end();
109	  } catch (err) { console.warn('[slack] Webhook failed:', err.message); }
110	}
