112	function logAgentRun(entry) {
113	  const estimateTokens = (text) => Math.ceil((text || '').length / 4);
114	  const estimateCost = (i, o) => (i * 3 + o * 15) / 1_000_000;
115	  const inputTokens = estimateTokens(entry.prompt || '');
116	  const outputTokens = estimateTokens(entry.output || '');
117	  const run = {
118	    id: Date.now().toString(36) + Math.random().toString(36).slice(2, 7),
119	    agentName: entry.agentName || 'unknown',
120	    prompt: (entry.prompt || '').slice(0, 200),
121	    source: entry.source || 'unknown',
122	    timestamp: new Date().toISOString(),
123	    duration: entry.duration || 0,
124	    status: entry.status || 'success',
125	    promptChars: (entry.prompt || '').length,
126	    outputChars: (entry.output || '').length,
127	    estimatedTokens: inputTokens + outputTokens,
128	    estimatedCost: estimateCost(inputTokens, outputTokens),
129	    error: entry.error || null,
130	    metadata: entry.metadata || {},
131	  };
132	  try { db.insertAgentRun(run); } catch (err) { console.error('[logAgentRun] DB insert failed:', err.message); }
133	  return run;
134	}
