292	// POST /api/orchestrations/approve/:runId/:nodeId
293	// Atomic claim: Map.delete returns true only for the first caller; subsequent
294	// concurrent requests get 409 instead of double-resolving the promise.
295	router.post('/orchestrations/approve/:runId/:nodeId', rateLimit('write'), (req, res) => {
296	  const key = `${req.params.runId}:${req.params.nodeId}`;
297	  const resolver = pendingApprovalResolvers.get(key);
298	  if (!resolver) return res.status(404).json({ error: 'No pending approval found' });
299	  const claimed = pendingApprovalResolvers.delete(key);
300	  if (!claimed) return res.status(409).json({ error: 'Approval already resolved' });
301	  clearTimeout(resolver.timer);
302	  saveApprovals(loadApprovals().filter(a => a.key !== key));
303	  resolver.resolve();
304	  res.json({ ok: true, action: 'approved' });
305	});
