337	
338	  let mermaid = 'graph TD\n';
339	  for (const node of orc.nodes) {
340	    const label = node.data?.label || node.id;
341	    const shape = node.data?.isStart ? `${node.id}([${label}])` : node.data?.isApproval ? `${node.id}{${label}}` : `${node.id}[${label}]`;
342	    mermaid += `  ${shape}\n`;
343	  }
344	  for (const edge of (orc.edges || [])) {
345	    const cond = orc.nodes.find(n => n.id === edge.target)?.data?.condition;
346	    mermaid += cond ? `  ${edge.source} -->|${cond}| ${edge.target}\n` : `  ${edge.source} --> ${edge.target}\n`;
347	  }
348	
349	  res.json({
350	    id: orc.id,
351	    name: orc.name,
352	    json: { nodes: orc.nodes, edges: orc.edges },
353	    mermaid,
354	    nodeCount: orc.nodes.length,
355	    edgeCount: (orc.edges || []).length,
356	  });
357	});
