359	// POST /api/orchestrations/run
360	router.post('/orchestrations/run', rateLimit('heavy'), async (req, res) => {
361	  res.setTimeout(0);
362	  const { nodes, edges, task } = req.body;
363	  if (!Array.isArray(nodes) || !task) return res.status(400).json({ error: 'nodes and task required' });
364	
365	  const nodeMap = Object.fromEntries(nodes.map(n => [n.id, n]));
366	  const order = topoSort(nodes, edges || []);
367	
368	  const config = loadConfig();
369	  const projects = discoverProjects(config.projectDirs);
370	  const agentContentMap = {};
371	
372	  const globalAgents = listAgents(path.join(CLAUDE_DIR, 'agents'));
373	  for (const a of globalAgents) agentContentMap[a.name] = a.body || a.raw;
374	
375	  for (const p of projects) {
376	    for (const a of p.agents) agentContentMap[a.name] = a.body || a.raw;
377	  }
378	
379	  const results = {};
380	  let lastOutput = task;
381	  const runId = genId();
382	  const startedAt = new Date().toISOString();
383	  const runLogs = [];
384	  let runStatus = 'completed';
385	  let clientDisconnected = false;
386	
387	  res.setHeader('Content-Type', 'text/event-stream');
388	  res.setHeader('Cache-Control', 'no-cache');
389	  res.setHeader('Connection', 'keep-alive');
390	  res.flushHeaders();
391	
392	  res.on('close', () => { clientDisconnected = true; });
393	
394	  const send = (data) => {
395	    runLogs.push(data);
396	    if (clientDisconnected) return;
397	    try { res.write(`data: ${JSON.stringify(data)}\n\n`); } catch {}
398	  };
399	
400	  async function executeNode(nodeId) {
401	    const node = nodeMap[nodeId];
402	    if (!node) return;
403	
404	    if (node.data?.isStart) {
405	      results[nodeId] = task;
406	      send({ type: 'done', nodeId, label: node.data?.label || nodeId, output: task, skipped: true });
407	      return;
408	    }
409	
410	    if (node.data?.isApproval) {
411	      const nodeLabel = node.data?.label || 'Approval';
412	      send({ type: 'waiting_approval', nodeId, label: nodeLabel });
413	      try {
414	        await waitForApproval(runId, nodeId, nodeLabel, node.data?.timeoutMinutes || 60);
415	        results[nodeId] = '[APPROVED]';
416	        send({ type: 'done', nodeId, label: nodeLabel, output: '[APPROVED]' });
417	      } catch (err) {
418	        runStatus = 'failed';
419	        results[nodeId] = `[REJECTED: ${err.message}]`;
420	        send({ type: 'error', nodeId, label: nodeLabel, error: err.message });
421	        throw err;
422	      }
423	      return;
424	    }
425	
426	    const agentName = node.data?.agentName;
427	    const baseInstructions = agentName ? (agentContentMap[agentName] || '') : '';
428	    const nodeInstructions = node.data?.instructions || '';
429	    const nodeLabel = node.data?.label || agentName || nodeId;
430	
431	    send({ type: 'start', nodeId, label: nodeLabel });
432	
433	    const incomingEdges = (edges || []).filter(e => e.target === nodeId);
434	    let context = '';
435	    if (incomingEdges.length > 0) {
436	      context = incomingEdges.map(e => {
437	        const prevLabel = nodeMap[e.source]?.data?.label || e.source;
438	        return `## Output from ${prevLabel}:\n${results[e.source] || ''}`;
439	      }).join('\n\n');
440	    } else {
441	      context = `## Task:\n${task}`;
442	    }
443	
444	    let prompt = '';
445	    if (baseInstructions) prompt += baseInstructions + '\n\n';
446	    if (nodeInstructions) prompt += `## Your Specific Task for This Step:\n${nodeInstructions}\n\n`;
447	    prompt += `---\n\n${context}\n\n`;
448	    prompt += `---\n\nIMPORTANT: Produce the actual deliverable directly. Do NOT write meta-commentary, evaluations, or descriptions of what you would do. Output only the finished work product itself.`;
449	
450	    const condition = node.data?.condition;
451	    if (condition) {
452	      const incomingOutputs = incomingEdges.map(e => results[e.source] || '').join('\n');
453	      if (!incomingOutputs.includes(condition)) {
454	        results[nodeId] = `[SKIPPED: condition "${condition}" not matched]`;
455	        send({ type: 'skipped', nodeId, label: nodeLabel, condition });
456	        return;
457	      }
458	    }
459	
460	    const maxRetries = Math.min(node.data?.retryCount || 0, 3);
461	    let attempt = 0;
462	    let nodeOutput = null;
463	    let lastErr = null;
464	
465	    while (attempt <= maxRetries) {
466	      const nodeStart = Date.now();
467	      try {
468	        if (attempt > 0) {
