706	// ── Durable executor ──────────────────────────────────────────────────────
707	//
708	// Walks the graph in topo order. For each step:
709	//   1. Mark step running + emit event
710	//   2. Create a Phase A `task` so capacity is tracked
711	//   3. Run claude (re-uses runClaudeSync from this module's top scope)
712	//   4. Mark step completed + complete the task
713	//   5. Pause on approval gates (durable — survives restart)
714	async function executeDurableRun(runId, orchestration, taskInput) {
715	  const nodes = orchestration.nodes || [];
716	  const edges = orchestration.edges || [];
717	  const nodeMap = Object.fromEntries(nodes.map((n) => [n.id, n]));
718	  const order = topoSort(nodes, edges);
719	
720	  orchRunner.markRunRunning(runId, order[0] || null);
721	
722	  let lastOutput = taskInput;
723	  const outputs = {};
724	
725	  for (const nodeId of order) {
726	    const node = nodeMap[nodeId];
727	    if (!node) continue;
728	
729	    // Start node — passthrough, no execution
730	    if (node.data?.isStart) {
731	      orchRunner.markStepSkipped(runId, nodeId);
732	      outputs[nodeId] = taskInput;
733	      continue;
734	    }
735	
736	    // Approval gate — pause durably
737	    if (node.data?.isApproval) {
738	      orchRunner.markStepPaused(runId, nodeId);
739	      orchRunner.markRunPaused(runId, nodeId);
740	      // The step row remains 'paused' until POST /steps/:nodeId/advance runs.
741	      // For now we end this executor invocation — caller will need to
742	      // re-trigger after the approval comes in. Simpler than promise-based
743	      // pause: keeps state durable.
744	      return;
745	    }
746	
747	    const agentName = node.data?.agentName;
748	    if (!agentName) {
749	      orchRunner.markStepFailed(runId, nodeId, 'node has no agentName');
750	      orchRunner.markRunFailed(runId, `step ${nodeId} missing agentName`);
751	      return;
752	    }
753	
754	    // Phase A: create a task to track capacity
755	    let task = null;
756	    try {
757	      task = tasks.createTask({
758	        agentId: agentName,
759	        source: 'orchestration',
760	        taskType: node.data?.taskType || 'workflow',
761	        title: node.data?.label || nodeId,
762	        prompt: node.data?.instructions || lastOutput,
763	        priority: node.data?.priority || 'p2',
764	        metadata: { runId, nodeId, orchestrationId: orchestration.id },
765	      });
766	    } catch (err) {
767	      orchRunner.markStepFailed(runId, nodeId, `task creation failed: ${err.message}`);
768	      orchRunner.markRunFailed(runId, err.message);
769	      return;
770	    }
771	
772	    orchRunner.markStepRunning(runId, nodeId, task.id);
773	    tasks.markRunning(task.id);
774	
775	    // Build prompt
776	    const prompt = composePrompt(agentName, node, lastOutput);
777	    let output;
778	    try {
779	      output = await runClaudeSync(prompt, (node.data?.timeoutMinutes || 60) * 60 * 1000);
780	      tasks.markComplete(task.id, output);
781	      orchRunner.markStepCompleted(runId, nodeId, output);
782	      outputs[nodeId] = output;
783	      lastOutput = output;
784	    } catch (err) {
785	      tasks.markFailed(task.id, err.message || String(err));
786	      orchRunner.markStepFailed(runId, nodeId, err.message || String(err));
787	      orchRunner.markRunFailed(runId, `step ${nodeId} failed: ${err.message || err}`);
788	      return;
789	    }
790	  }
791	
792	  orchRunner.markRunCompleted(runId, lastOutput);
793	}
