795	// Re-execute a single node (retry path).
796	async function executeSingleNode(runId, orchestration, taskInput, nodeId) {
797	  const nodes = orchestration.nodes || [];
798	  const node = nodes.find((n) => n.id === nodeId);
799	  if (!node) throw new Error(`node ${nodeId} not in orchestration`);
800	  const agentName = node.data?.agentName;
801	  if (!agentName) throw new Error('node has no agentName');
802	
803	  const task = tasks.createTask({
804	    agentId: agentName,
805	    source: 'orchestration:retry',
806	    taskType: node.data?.taskType || 'workflow',
807	    title: `Retry: ${node.data?.label || nodeId}`,
808	    prompt: node.data?.instructions || taskInput,
809	    metadata: { runId, nodeId, retry: true },
810	  });
811	
812	  orchRunner.markStepRunning(runId, nodeId, task.id);
813	  tasks.markRunning(task.id);
814	
815	  try {
816	    const output = await runClaudeSync(
817	      composePrompt(agentName, node, taskInput),
818	      (node.data?.timeoutMinutes || 60) * 60 * 1000,
819	    );
820	    tasks.markComplete(task.id, output);
821	    orchRunner.markStepCompleted(runId, nodeId, output);
822	  } catch (err) {
823	    tasks.markFailed(task.id, err.message || String(err));
824	    orchRunner.markStepFailed(runId, nodeId, err.message || String(err));
825	  }
826	}
