25	function runClaudeSync(prompt, timeoutMs = 120000) {
26	  return new Promise((resolve, reject) => {
27	    const claudePath = process.env.CLAUDE_PATH || 'claude';
28	    const childEnv = { ...process.env, HOME: os.homedir() };
29	    delete childEnv.CLAUDECODE;
30	    delete childEnv.CLAUDE_CODE_ENTRYPOINT;
31	    delete childEnv.CLAUDE_CODE_ENABLE_SDK_FILE_CHECKPOINTING;
32	    delete childEnv.CLAUDE_AGENT_SDK_VERSION;
33	    const proc = spawn(claudePath, ['-p'], { env: childEnv });
34	    let out = '', err = '';
35	    let killed = false;
36	
37	    const timer = setTimeout(() => {
38	      killed = true;
39	      proc.kill('SIGTERM');
40	      setTimeout(() => { try { proc.kill('SIGKILL'); } catch {} }, 5000);
41	    }, timeoutMs);
42	
43	    proc.stdout.on('data', d => { out += d.toString(); });
44	    proc.stderr.on('data', d => { err += d.toString(); });
45	    proc.on('close', code => {
46	      clearTimeout(timer);
47	      if (killed) reject(new Error(`Execution timed out after ${timeoutMs / 1000}s`));
48	      else if (code !== 0) reject(new Error(err.trim() || `claude exited ${code}`));
49	      else resolve(out.trim());
50	    });
51	    proc.on('error', (e) => { clearTimeout(timer); reject(e); });
52	    proc.stdin.write(prompt, 'utf8');
53	    proc.stdin.end();
54	  });
55	}
