140	router.post('/webhooks/trigger/:id', rateLimit('heavy'), async (req, res) => {
141	  const webhooks = loadWebhooks();
142	  const webhook = webhooks.find(w => w.id === req.params.id);
143	  if (!webhook) return res.status(404).json({ error: 'Webhook not found' });
144	
145	  const secret = req.headers['x-webhook-secret'];
146	  if (!secret || secret !== webhook.secret) return res.status(401).json({ error: 'Invalid webhook secret' });
147	
148	  webhook.lastTriggeredAt = new Date().toISOString();
149	  webhook.triggerCount = (webhook.triggerCount || 0) + 1;
150	  saveWebhooks(webhooks);
151	
152	  const payload = JSON.stringify(req.body || {}, null, 2);
153	  const startTime = Date.now();
154	
155	  try {
156	    if (webhook.agentName) {
157	      const prompt = buildScheduledPrompt({ agentName: webhook.agentName, prompt: `Webhook triggered: ${webhook.name}\n\nPayload:\n${payload}` });
158	      const output = await runClaudeSync(prompt, 300000);
159	      logAgentRun({ agentName: webhook.agentName, prompt: `Webhook: ${webhook.name}`, output, source: 'webhook', duration: Date.now() - startTime, status: 'success', metadata: { webhookId: webhook.id } });
160	      res.json({ success: true, output: output.slice(0, 500) });
161	    } else if (webhook.orchestrationId) {
162	      const orc = loadOrchestrations().find(o => o.id === webhook.orchestrationId);
163	      if (!orc) return res.status(404).json({ error: 'Orchestration not found' });
164	      const orcResults = {};
165	      let orcLastOutput = payload;
166	      const orcOrder = topoSort(orc.nodes, orc.edges || []);
167	      const orcNodeMap = Object.fromEntries(orc.nodes.map(n => [n.id, n]));
168	      const agentContentMap = {};
169	      const globalAgents = listAgents(path.join(CLAUDE_DIR, 'agents'));
170	      for (const a of globalAgents) agentContentMap[a.name] = a.body || a.raw;
171	
172	      for (const nid of orcOrder) {
173	        const nd = orcNodeMap[nid];
174	        if (!nd) continue;
175	        if (nd.data?.isStart) { orcResults[nid] = `Webhook: ${webhook.name}\n\n${payload}`; continue; }
176	        const aName = nd.data?.agentName;
177	        const baseInst = aName ? (agentContentMap[aName] || '') : '';
178	        const nodeInst = nd.data?.instructions || '';
179	        const incoming = (orc.edges || []).filter(e => e.target === nid);
180	        let ctx = incoming.length > 0
181	          ? incoming.map(e => `## Output from ${orcNodeMap[e.source]?.data?.label || e.source}:\n${orcResults[e.source] || ''}`).join('\n\n')
182	          : `## Task:\n${payload}`;
183	        let p = '';
184	        if (baseInst) p += baseInst + '\n\n';
185	        if (nodeInst) p += `## Your Specific Task:\n${nodeInst}\n\n`;
186	        p += `---\n\n${ctx}\n\n---\n\nIMPORTANT: Produce the actual deliverable directly.`;
187	        const nStart = Date.now();
188	        try {
189	          const out = await runClaudeSync(p);
190	          orcResults[nid] = out;
191	          orcLastOutput = out;
192	          logAgentRun({ agentName: aName || 'custom', prompt: p.slice(0, 500), output: out, source: 'webhook', duration: Date.now() - nStart, status: 'success', metadata: { webhookId: webhook.id, orchestrationId: webhook.orchestrationId, nodeId: nid } });
193	        } catch (err) {
194	          logAgentRun({ agentName: aName || 'custom', prompt: p.slice(0, 500), output: '', source: 'webhook', duration: Date.now() - nStart, status: 'error', error: err.message, metadata: { webhookId: webhook.id } });
195	          return res.json({ success: false, error: err.message });
196	        }
197	      }
198	      res.json({ success: true, output: orcLastOutput.slice(0, 500) });
199	    } else {
200	      res.status(400).json({ error: 'Webhook has no agent or orchestration configured' });
201	    }
202	  } catch (err) {
203	    logAgentRun({ agentName: webhook.agentName || 'webhook', prompt: `Webhook: ${webhook.name}`, output: '', source: 'webhook', duration: Date.now() - startTime, status: 'error', error: err.message, metadata: { webhookId: webhook.id } });
204	    res.status(500).json({ success: false, error: err.message });
205	  }
